"ros.exc.samplenote": ["Sample data: the real analysis of this store appears here once the real export has been run.", "Beispieldaten: Die echte Analyse dieser Filiale erscheint hier, sobald der echte Export ausgeführt wurde."],
"ros.repro.h": ["Reproduce it", "Selbst nachvollziehen"],
"ros.repro.p": ["Everything is reproducible from the public Kaggle data. This site publishes <strong>aggregates only</strong> (weekly totals, error statistics) – not the raw Kaggle files.", "Alles ist aus den öffentlichen Kaggle-Daten reproduzierbar. Diese Seite veröffentlicht <strong>nur Aggregate</strong> (Wochensummen, Fehlerstatistiken) – nicht die Kaggle-Rohdateien."],
"ros.repro.1": ["the full training and prediction pipeline", "die vollständige Trainings- und Prognosepipeline"],
"ros.repro.2": ["refits the final model and writes the JSON files for this page", "trainiert das finale Modell neu und schreibt die JSON-Dateien für diese Seite"],
"ros.repro.3": ["recorded validation and Kaggle numbers, plus the experiment tables", "erfasste Validierungs- und Kaggle-Werte sowie die Experimenttabellen"],
/* ===== project 2: inventory ===== */
"inv.title": ["Inventory planning", "Bestandsplanung"],
