"inv.m.h": ["Method and assumptions", "Methode und Annahmen"],
"inv.m.f.h": ["Formulas", "Formeln"],
"inv.m.f.legend": ["μ = mean daily demand, σ<sub>e</sub> = daily forecast-error standard deviation (real), L = lead time, C = order cycle, z = service factor, G = standard normal loss function, h = holding rate, c = cost ratio, p = stock-out penalty, N = trading days per year.", "μ = mittlere Tagesnachfrage, σ<sub>e</sub> = Standardabweichung des täglichen Prognosefehlers (real), L = Wiederbeschaffungszeit, C = Bestellzyklus, z = Sicherheitsfaktor, G = Verlustfunktion der Standardnormalverteilung, h = Lagerkostensatz, c = Kostenquote, p = Fehlmengenkosten, N = Handelstage pro Jahr."],
"inv.m.a.h": ["Assumptions", "Annahmen"],
"inv.m.a.1": ["Continuous-review (s, Q) policy; forecast errors are independent from day to day and roughly normal.", "Kontinuierliche (s, Q)-Politik; Prognosefehler sind von Tag zu Tag unabhängig und annähernd normalverteilt."],
"inv.m.a.2": ["Lead time is fixed; lead-time variability is covered in Project 4.", "Die Wiederbeschaffungszeit ist fest; ihre Schwankung behandelt Projekt 4."],
"inv.m.a.3": ["Unmet demand is lost, not backordered.", "Nicht erfüllte Nachfrage geht verloren und wird nicht nachgeliefert."],
"inv.m.a.4": ["Sales are in euros, so stock is measured in euros at cost; there are no unit counts in the open data.", "Umsätze sind in Euro angegeben, daher wird der Bestand in Euro zu Einstandswerten gemessen; die offenen Daten enthalten keine Stückzahlen."],
"inv.m.a.5": ["Cost parameters are modeled assumptions you can change; demand and forecast error come from the real model.", "Kostenparameter sind Modellannahmen, die Sie ändern können; Nachfrage und Prognosefehler stammen aus dem realen Modell."],
/* ===== project 3: sourcing ===== */
"src.title": ["Sourcing & procurement", "Einkauf & Beschaffung"],
"src.eyebrow": ["Project 3 · Sourcing & procurement", "Projekt 3 · Einkauf & Beschaffung"],
"src.h1": ["Supplier scorecard, total cost of ownership and sourcing strategy", "Lieferantenbewertung, Total Cost of Ownership und Beschaffungsstrategie"],
"src.lead": ["Five small tools that mirror a sourcing decision: rank suppliers, compare real cost beyond the unit price, find where the spend is, decide make or buy, and size a second source.", "Fünf kleine Werkzeuge, die eine Beschaffungsentscheidung abbilden: Lieferanten bewerten, die realen Kosten jenseits des Stückpreises vergleichen, erkennen, wo das Volumen liegt, Make or Buy entscheiden und eine zweite Quelle dimensionieren."],
"src.t1.h": ["Supplier scorecard", "Lieferantenbewertung"],
